/* Nexus Hub Design Studio · fristående demo, inga produktionsdata. */
(function(){
'use strict';
var N=window.NEXUS, KEY='nexus-design-studio-v1';
if(!N){document.getElementById('app').textContent='Kunde inte ladda komponentregistret.';return;}
var DEFAULT={theme:'velvet',view:'home',labels:false,edit:false,picks:{nav:1,surface:0,mediaCard:0,filter:0,graph:0,hero:0,knowledge:0},hidden:[],order:['films','stories','knowledge','files','inbox','plugins'],watched:{},plugins:{},inboxRead:{},fontSize:18,focus:false,selectedStory:'dyatlov',ideaBoard:[]};
var state={};
try{state=Object.assign({},DEFAULT,JSON.parse(localStorage.getItem(KEY)||'{}'));}catch(e){state=Object.assign({},DEFAULT);}
state.picks=Object.assign({},DEFAULT.picks,state.picks||{});
state.order=Array.isArray(state.order)?state.order:DEFAULT.order.slice();
state.hidden=Array.isArray(state.hidden)?state.hidden:[];
state.ideaBoard=Array.isArray(state.ideaBoard)?state.ideaBoard:[];var knownIdeaKeys=new Set((window.NEXUS_IDEAS||[]).map(function(x){return String(x.model)+'::'+String(x.id);}));state.ideaBoard=state.ideaBoard.filter(function(key){return typeof key==='string'&&knownIdeaKeys.has(key);});
state.collapsedSections=state.collapsedSections&&typeof state.collapsedSections==='object'?state.collapsedSections:{};
var runtime={sheet:null,slot:null,selectedMedia:null,selectedNode:null,selectedFile:null,filmFilter:'Alla',mediaSearch:'',researchQuery:'',researchModel:'Alla',researchLimit:25,builderFilter:'',readerFoot:false,chapter:0,selectedIdeaKey:null,aiModuleLimit:12};
var byId=function(id){return document.getElementById(id);};
var esc=function(x){return String(x==null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
var attr=function(x){return esc(x);};
var variant=function(id){return Number(state.picks[id]||0);};
var family=function(id){return N.families.find(function(f){return f.id===id;});};
var familyName=function(id){var f=family(id);return f?f.name:id;};
var chosen=function(id){var f=family(id);return f?(f.options[variant(id)]||f.options[0]):'';};
var nVariants=N.families.reduce(function(n,f){return n+f.options.length;},0);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){toast('Lokal lagring kunde inte användas');}}
function changePick(id,value){if(!family(id))return;state.picks[id]=Math.max(0,Math.min(value,family(id).options.length-1));save();render();toast(familyName(id)+' · '+chosen(id));}
function toast(message){var old=document.querySelector('.toast');if(old)old.remove();var node=document.createElement('div');node.className='toast';node.textContent=message;document.body.appendChild(node);setTimeout(function(){node.remove();},2200);}
function targetOption(id){var f=family(id),meta=(window.NEXUS_IDEA_INTEGRATION&&window.NEXUS_IDEA_INTEGRATION.families||[]).find(function(x){return x.id===id;});if(!f||!meta)return null;var i=variant(id)-meta.baseCount;return i>=0&&meta.options[i]?meta.options[i]:null;}
function targetWidget(host){var rows=(window.NEXUS_IDEA_INTEGRATION&&window.NEXUS_IDEA_INTEGRATION.families||[]).filter(function(x){return x.host===host;}).map(function(meta){var o=targetOption(meta.id);return o?{meta:meta,option:o}:null;}).filter(Boolean);if(!rows.length)return '';return '<div class="idea-live-host idea-live-host-'+attr(host)+'"><div class="eyebrow">AI-INTEGRERAD KOMPONENT · LOKAL DEMO</div>'+rows.map(function(row){var f=family(row.meta.id),idx=variant(f.id)-row.meta.baseCount,style=idx%3;return '<article class="idea-live-variant idea-live-style-'+style+'" data-live-family="'+attr(f.id)+'"><div class="idea-live-title"><b>'+esc(f.name)+'</b><span>'+row.option.sources.length+' källfynd</span></div><p>'+esc(row.option.change)+'</p><div class="idea-live-controls"><button class="mini-btn" data-edit-slot="'+attr(f.id)+'">Ändra variant</button><button class="mini-btn" data-action="builder">Alla komponenter</button></div><small>Vald variant '+(idx+1)+' · sparas lokalt · exempeldata</small></article>';}).join('')+'</div>';}
function slot(id,inner,extra){var target=targetWidget(id);return '<div class="section-slot v-'+variant(id)+' '+(extra||'')+'" data-slot="'+attr(id)+'"><span class="design-tag">'+esc(familyName(id))+' · '+esc(chosen(id))+' ['+id+':'+variant(id)+']</span><button class="edit-chip" data-edit-slot="'+attr(id)+'" title="Välj designvariant">✦ Byt</button>'+inner+target+'</div>';}
function section(title,body,action){var sid=title.toLowerCase().replace(/[^a-z0-9åäö]+/g,'-');var count=title==='Dina moduler'?N.data.modules.length:title==='Fortsätt upptäcka'?N.data.media.length:title==='Utforska dossierer'?N.data.stories.length:title==='Arkivet'?N.data.files.length:null;var collapsed=variant('ux010')>0&&!!state.collapsedSections[sid];var classes='section'+(variant('ux004')?' ux-tonal ux-tonal-'+variant('ux004'):'');return '<section class="'+classes+'" data-section-id="'+attr(sid)+'"><div class="section-head"><h2>'+esc(title)+(variant('ux002')&&count!==null?'<span class="ux-count'+(variant('ux002')>1?' ux-count-strong':'')+'">'+count+'</span>':'')+'</h2>'+(action||'')+(variant('ux010')?'<button class="ux-collapse" data-toggle-section="'+attr(sid)+'" aria-expanded="'+(!collapsed)+'">'+(collapsed?'Visa +':'Dölj −')+'</button>':'')+'</div>'+(collapsed?'':'<div class="section-content">'+body+'</div>')+'</section>';}
function setView(id){if(!N.views.some(function(v){return v.id===id;}))return;state.view=id;runtime.sheet=null;save();render();window.scrollTo(0,0);}
function button(label,action,cls){return '<button class="action-btn '+(cls||'')+'" data-action="'+attr(action)+'">'+label+'</button>';}
function subhead(title,desc){return '<div class="intro"><div><div class="eyebrow">NEXUS HUB / DESIGN STUDIO</div><h1>'+esc(title)+'</h1>'+(desc?'<p>'+desc+'</p>':'')+'</div></div>';}
function topbar(){var theme=N.themes.find(function(t){return t.id===state.theme;})||N.themes[0];return slot('header','<header class="topbar"><button class="icon-btn" data-action="menu" title="Visa alla vyer">☰</button><div class="logo">NEXUS <b>STUDIO</b><small>'+esc(theme.name)+'</small></div><div class="top-actions"><button class="icon-btn" data-action="search" title="Sök">⌕</button><button class="icon-btn '+(state.labels?'active':'')+'" data-action="labels" title="Visa/dölj variantnamn">▤</button><button class="action-btn primary" data-action="builder">✦ Bygg</button></div></header>','header-wrapper');}
function sidebar(){return '<aside class="sidebar"><div class="side-brand">NEXUS <span>STUDIO</span></div>'+N.views.map(function(v){return '<button class="side-link '+(state.view===v.id?'current':'')+'" data-go="'+v.id+'"><b>'+v.icon+'</b>'+esc(v.name)+'</button>';}).join('')+'<div class="side-foot">DESIGNLABB · DEMODATA<br>'+nVariants+' komponentvarianter<br>527 researchfynd</div></aside>';}
function quickAction(){return slot('quick','<button class="quick-fab" data-action="quick" aria-label="Snabbåtgärder">+</button>');}
function bottomNav(){var main=[N.views[0],N.views[1],N.views[2],N.views[3],N.views[4]];var mid=variant('nav')===1;var links=main.map(function(v,i){return (mid&&i===2?'<button class="nav-plus" data-action="quick" aria-label="Snabbåtgärd">+</button>':'')+'<button class="nav-item '+(state.view===v.id?'active':'')+' '+(state.view===v.id&&variant('ux005')?'ux-active-accent ux-accent-'+variant('ux005'):'')+'" data-go="'+v.id+'"><b>'+v.icon+'</b><span>'+esc(v.name==='Film & serier'?'Film':v.name==='Kunskapsbank'?'Kunskap':v.name)+'</span></button>';}).join('');return slot('nav','<nav class="bottomnav v-'+variant('nav')+'" aria-label="Huvudnavigation">'+links+'</nav>','nav-wrapper');}
function previewBanner(){return '<div class="studio-banner"><div><strong>DIN BYGGSTUDIO</strong><br><small>Kort tryck öppnar · håll inne 0,5 s för designval</small></div><button data-action="labels">'+(state.labels?'✓ Etiketter på':'▤ Visa etiketterna')+'</button></div>';}
function hero(){var v=variant('hero');var titles=['Ditt universum. Din design.','Ett eget universum av berättelser.','Fortsätt där du slutade.','Vad vill du upptäcka?','Varje mysterium har en början.','Din kunskap, helt din.','Välkommen tillbaka.','Överblick över allt.','Allt samlat på ett ställe.'];return slot('hero','<div class="hero v-'+v+'"><div class="eyebrow">PERSONLIGT ARKIV · DEMO</div><h1>'+titles[v]+'</h1><p>Utforska dina filmer, mysterier och kunskapsobjekt. Byt ut varje del och forma din egen Nexus Hub.</p><div class="hero-buttons">'+button('Börja utforska','builder','primary')+'<button class="action-btn ghost" data-go="films">Film & serier →</button></div></div>');}
function moduleCard(m){return '<article class="card module-card clickable" data-go="'+m.id+'"><div class="module-icon">'+m.icon+'</div><div><div class="module-tag">'+m.tag+'</div><h3>'+esc(m.name)+'</h3><p>'+esc(m.desc)+'</p></div></article>';}
function modules(){var ordered=state.order.map(function(id){return N.data.modules.find(function(m){return m.id===id;});}).filter(Boolean).filter(function(m){return !state.hidden.includes(m.id);});return slot('launcher','<div class="modules">'+ordered.map(moduleCard).join('')+'</div>');}
function stats(){var cls=variant('ux009')?'stats ux-stats-pills':'stats';return slot('stats','<div class="'+cls+'"><div class="card stat"><small>Filmer & serier · demo</small><strong>'+N.data.media.length+'</strong></div><div class="card stat"><small>Berättelser · demo</small><strong>'+N.data.stories.length+'</strong></div><div class="card stat"><small>Dokument · demo</small><strong>'+N.data.files.length+'</strong></div></div>');}
function postercard(m){return '<div class="poster-card" data-open-media="'+m.id+'"><div class="poster" style="background:'+m.poster+'"><span class="poster-glyph">'+m.glyph+'</span><span class="poster-badge">'+(state.watched[m.id]?'✓ Sett':m.seen?'◉ Sett':'◌ Vill se')+'</span></div><div class="poster-info"><h3>'+esc(m.title)+'</h3><p>'+m.year+' · '+m.type+' · ★ '+m.rating+'</p></div></div>';}
function continuation(){var mode=variant('ux003');if(mode===1)return slot('continue','<div class="ux-continue-cards">'+N.data.media.slice(0,4).map(function(m){return '<button class="ux-continue-card" data-open-media="'+m.id+'"><span class="ux-art" style="background:'+m.poster+'">'+m.glyph+'</span><span><b>'+esc(m.title)+'</b><small>'+esc(m.progress)+'</small></span><b>›</b></button>';}).join('')+'</div>');if(mode===2)return slot('continue','<div class="ux-continue-grid">'+N.data.media.slice(0,4).map(postercard).join('')+'</div>');return slot('continue','<div class="poster-row">'+N.data.media.slice(0,6).map(postercard).join('')+'</div>');}
function timeline(){var rows=[['◈','Läsning','Djatlovpasset · anteckning uppdaterad','Idag'],['▣','Film & serier','Severance · fortsätt säsong 2','Igår'],['✳','Kunskapsbank','Nya relationer i forskningsgrafen','Måndag']];return slot('activity','<div class="simple-list">'+rows.map(function(r){return '<div class="card list-row" data-go="activity"><span class="row-ico">'+r[0]+'</span><div><strong>'+r[1]+'</strong><small>'+r[2]+'</small></div><span class="right">'+r[3]+'</span></div>';}).join('')+'</div>');}
function uxSystemStatus(){if(!variant('ux007'))return '';var extra=variant('ux007')>1?'<div><i></i><b>Komponentbyggare</b><small>'+N.families.filter(function(f){return f.group==='AI-moduler';}).length+' integrerade AI-moduler</small></div>':'';return section('Systemstatus','<div class="ux-status"><div><i></i><b>Prototyp</b><small>Aktiv vy: '+esc((N.views.find(function(v){return v.id===state.view;})||N.views[0]).name)+'</small></div><div><i></i><b>Demodata</b><small>'+N.data.media.length+' titlar · '+N.data.stories.length+' berättelser</small></div><div><i class="muted"></i><b>Synkronisering</b><small>Inte ansluten i denna prototyp</small></div>'+extra+'</div>');}
function uxRandomDiscovery(){if(!variant('ux008'))return '';return section('Slumpmässig upptäckt','<div class="ux-discovery"><div><b>Upptäck en berättelse</b><p>Öppna en slumpmässigt vald dossier från demobiblioteket.</p></div><button class="action-btn primary" data-action="ux-random">Överraska mig</button></div>');}
function home(){return previewBanner()+hero()+slot('home','<p class="notice">Startsida · lokala demomoduler</p>'+targetWidget('home'))+targetWidget('global')+builtAIModules()+uxSystemStatus()+section('Överblick',stats())+section('Dina moduler',modules(),'<button class="smalllink" data-action="builder">Anpassa ↗</button>')+section('Fortsätt upptäcka',continuation(),'<button class="smalllink" data-go="films">Visa allt →</button>')+uxRandomDiscovery()+section('Senaste i Nexus Hub',timeline());}
function filterChips(){return slot('filter','<div class="chips">'+['Alla','Film','Serie','Sett','Inte sett','Sci-fi','Mystik','Drama'].map(function(f){return '<button class="chip '+(runtime.filmFilter===f?'active':'')+'" data-filter="'+f+'">'+f+'</button>';}).join('')+'</div>');}
function filteredMedia(){return N.data.media.filter(function(m){var f=runtime.filmFilter;if(f==='Film'||f==='Serie')return m.type===f;if(f==='Sett')return !!(state.watched[m.id]||m.seen);if(f==='Inte sett')return !(state.watched[m.id]||m.seen);if(['Sci-fi','Mystik','Drama'].includes(f))return m.genres.includes(f);return true;}).filter(function(m){return m.title.toLocaleLowerCase().includes(runtime.mediaSearch.toLocaleLowerCase());});}
function filmGrid(){var items=filteredMedia();return slot('mediaLayout','<div class="poster-grid">'+(items.length?items.map(postercard).join(''):'<p class="nothing">Inga matchande filmer eller serier.</p>')+'</div>');}
function films(){return subhead('Film & serier','Testa helt olika filmkort, affischgrid, filter och detaljlayouter.')+'<div class="stack"><input class="studio-search" type="search" placeholder="Sök i demobiblioteket…" id="mediaSearch" value="'+attr(runtime.mediaSearch)+'"></div>'+section('Välj ett filter',filterChips())+section('Bibliotek · '+filteredMedia().length+' titlar',slot('mediaCard',filmGrid()))+section('Dina fortsätt-kort',continuation());}
function storiesGrid(){return N.data.stories.map(function(s){return '<article class="card story-card clickable" data-open-story="'+s.id+'"><div class="story-symbol">'+s.icon+'</div><div class="eyebrow">'+esc(s.eyebrow)+'</div><h3 class="story-title">'+esc(s.title)+'</h3><p>'+esc(s.desc)+'</p></article>';}).join('');}
function stories(){return subhead('Berättelser & mysterier','Ett fiktivt bibliotek för att pröva läsupplevelse och informationshierarki.')+section('Utforska dossierer',slot('storyLayout',slot('storyCard','<div class="story-grid">'+storiesGrid()+'</div>')))+section('Fortsätt läsa',slot('continue','<div class="card list-row clickable" data-open-story="dyatlov"><span class="row-ico">◈</span><div><strong>Djatlovpasset</strong><small>Fortsätt från kapitel 2 · demo</small></div><span class="right">→</span></div>'));}
function reader(){var s=N.data.stories.find(function(x){return x.id===state.selectedStory;})||N.data.stories[0];var heads=['Den sista expeditionen','Spåren på bergssluttningen','Frågor och teorier'];var paragraphs=[['Vinterskymningen hade redan lagt sig över bergssluttningen när expeditionens sista kända etapp inleddes. Vind, kyla och svår terräng skulle bli avgörande delar av berättelsen.','Den här läsvyn är exempeltext för designlaboratoriet, inte en historiskt verifierad redogörelse. Syftet är att kunna jämföra läsbarhet, källhantering, kapitelindelning och typografi.','När ett källmaterial presenteras behöver det gå att följa vad som är observation, tolkning och osäkerhet. En tydlig källpanel kan hjälpa utan att störa själva läsningen.'],['En tidslinje ger läsaren orientering. En dossier ger detaljer. Båda behövs, men de kan presenteras på många olika sätt.','I detta kapitel kan du testa fotnotspanelen, öka textstorleken, markera en läsposition och växla fokusläge. Allt sparas endast i din egen webbläsare.'],['Flera möjliga förklaringar kan beskrivas sida vid sida utan att en av dem förklaras bevisad.','Designstudion används för att hitta lämplig form för sådan osäkerhet: graf, källkort, tidslinje eller redaktionellt berättande.']];return subhead('Läsaren','Kapitel, fotnoter, läsro och typografi med riktig interaktion.')+slot('readerTools','<div class="reader-toolbar">'+button('Aa −','font-minus')+'<span class="chip">'+state.fontSize+' px</span>'+button('Aa +','font-plus')+button('☷ Kapitel','chapters')+button(runtime.readerFoot?'✕ Källpanel':'◈ Fotnoter','footnote')+button(state.focus?'Avsluta fokus':'Fokusläge','focus')+'</div>')+slot('reader','<article class="reader-paper"><div class="eyebrow">'+esc(s.eyebrow)+'</div><h1>'+esc(s.title)+'</h1><div class="chips"><span class="chip">KAPITEL '+(runtime.chapter+1)+'/3</span><span class="chip">Lästid · demo</span></div><h2 style="font-family:var(--serif);font-weight:400">'+heads[runtime.chapter]+'</h2><div class="reader-text" style="font-size:'+state.fontSize+'px">'+paragraphs[runtime.chapter].map(function(p,i){return '<p class="'+(i===0?'drop':'')+'">'+p+'</p>';}).join('')+'</div>'+(runtime.readerFoot?'<aside class="source-note"><strong>Källpanel · demonstration</strong><p>Här kan källor, ursprungsinformation och osäkerheter visas parallellt med lästexten. Detta är testinnehåll.</p></aside>':'')+'<div class="control-row" style="margin-top:22px">'+button('← Föregående','chapter-prev')+button('Nästa kapitel →','chapter-next','primary')+'</div></article>');}
function graph(){var nodes=N.data.nodes;var cx=50,cy=42;return slot('graph','<div class="graph-box"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><g stroke="var(--accent)" stroke-opacity=".35" stroke-width=".45">'+nodes.slice(1).map(function(n){return '<line x1="'+cx+'" y1="'+cy+'" x2="'+n.x+'" y2="'+n.y+'"/>';}).join('')+'</g></svg>'+nodes.map(function(n,i){return '<button class="graph-node '+(i===0?'main-node':'')+'" style="left:'+n.x+'%;top:'+n.y+'%" data-node="'+attr(n.id)+'">'+esc(n.id)+'</button>';}).join('')+'</div>');}
function knowledge(){var cards=N.data.nodes.map(function(n,i){return '<div class="card knowledge-item" data-node="'+attr(n.id)+'"><span class="node-ico">'+(i?'◇':'✳')+'</span><div><strong>'+esc(n.id)+'</strong><small>'+esc(n.kind)+' · klicka för relationer</small></div><span class="right" style="margin-left:auto;color:var(--accent)">↗</span></div>';}).join('');return subhead('Kunskapsbank','Utforska graf, objekt, backlinks, metadata och samband.')+section('Relationskarta',slot('knowledge','<div class="knowledge-wrap">'+graph()+'<div class="knowledge-items">'+cards+'</div></div>'))+section('Utforska vidare','<div class="card list-row clickable" data-go="files"><span class="row-ico">▤</span><div><strong>Källfiler och dokument</strong><small>Öppna tillhörande arkiv</small></div><span class="right">→</span></div>');}
function files(){return subhead('Utforska filer','Olika dokumentvyer, filkort och metadata utan riktig filåtkomst.')+section('Arkivet',slot('fileLayout',slot('fileCard','<div class="file-grid">'+N.data.files.map(function(f,i){return '<div class="card file-card" data-file="'+i+'"><div class="file-icon">'+f.icon+'</div><div><h3>'+esc(f.name)+'</h3><p>'+esc(f.type)+' · '+esc(f.size)+'</p></div></div>';}).join('')+'</div>')))+section('Mappens detaljer','<div class="callout"><div class="eyebrow">ARKIV · DEMO</div><p>Alla dokument här är exempelobjekt. Inga privata filer läses, skickas eller ändras.</p></div>');}
function inbox(){var msgs=[['◈','Nytt källförslag','Ett nytt forskningsspår kan granskas','Idag'],['▤','Dokument till inkorgen','Metadata väntar på sortering','Igår'],['✳','Relationsförslag','Två ämnen kan kopplas samman','Måndag']];return subhead('Inkorg','Jämför täta rader, meddelandekort och olika prioriteringsvyer.')+section('3 exempelposter',slot('inbox','<div class="simple-list">'+msgs.map(function(m,i){return '<div class="card list-row"><span class="row-ico">'+m[0]+'</span><div><strong>'+esc(m[1])+(state.inboxRead[i]?' ✓':'')+'</strong><small>'+esc(m[2])+'</small></div><button class="mini-btn" data-inbox="'+i+'">'+(state.inboxRead[i]?'Ångra':'Hantera')+'</button></div>';}).join('')+'</div>'));}
function plugins(){return subhead('Plugins & verktyg','Plugin-kort, direkta växlar, status och app-galleri i demomiljö.')+section('Dina verktyg',slot('plugin','<div class="utility-grid">'+N.data.plugins.map(function(p,i){var on=state.plugins[i]!==false;return '<div class="card utility-card"><span class="utility-icon">'+p.icon+'</span><div style="flex:1"><h3>'+esc(p.name)+'</h3><small>'+esc(p.desc)+'</small></div><button class="switch '+(on?'on':'')+'" role="switch" aria-checked="'+on+'" aria-label="Växla '+esc(p.name)+'" data-plugin="'+i+'"><i></i></button></div>';}).join('')+'</div>'))+'<p class="notice">Växlarna är lokala demonstrationer och styr inga riktiga plugins.</p>';}
function activity(){return subhead('Aktivitet','En sammanställning av lokala exempelaktiviteter.')+section('Senaste händelser',timeline())+section('Designhistorik','<div class="callout"><p>Dina aktuella designval sparas automatiskt i webbläsaren. Exportera en konfigurationsfil för att bevara eller dela dem.</p>'+button('Exportera mina val','export','primary')+'</div>');}
function settings(){return subhead('Inställningar','Justera appens utseende och hantera dina lokala konfigurationer.')+targetWidget('settings')+('<section class="idea-live-rules"><div class="eyebrow">AKTIVA GLOBALA DESIGNREGLER</div><p>'+esc(chosen('designRules'))+'</p><button class="mini-btn" data-edit-slot="designRules">Välj regel</button></section>')+section('Designriktning','<div class="control-row">'+N.themes.map(function(t){return '<button class="seg '+(state.theme===t.id?'active':'')+'" data-theme="'+t.id+'">'+esc(t.name)+'</button>';}).join('')+'</div>')+section('Din design','<div class="stack"><div class="card list-row" data-action="builder"><span class="row-ico">✦</span><div><strong>Alla komponenter</strong><small>'+N.families.length+' komponentfamiljer · '+nVariants+' varianter</small></div><span class="right">→</span></div><div class="card list-row" data-action="labels"><span class="row-ico">▤</span><div><strong>Visa namn på valda alternativ</strong><small>För skärmbilder och återkoppling</small></div><span class="right">'+(state.labels?'PÅ':'AV')+'</span></div><div class="card list-row" data-action="edit"><span class="row-ico">✎</span><div><strong>Redigeringsknappar</strong><small>Visa Byt på alla moduler</small></div><span class="right">'+(state.edit?'PÅ':'AV')+'</span></div></div>')+section('Exportera & återställ','<div class="control-row">'+button('↓ Exportera JSON','export','primary')+button('↑ Importera JSON','import')+button('Återställ allt','reset')+'</div><p class="notice">Ingen inloggning och ingen synk mellan enheter. Designinställningarna ligger i den här webbläsaren tills de exporteras eller rensas.</p>');}
function ideaKey(x){return x.model+'::'+x.id;}
function ideaSelected(x){return state.ideaBoard.indexOf(ideaKey(x))>=0;}
function ideaAction(x){return '<button class="action-btn '+(ideaSelected(x)?'primary':'')+'" data-idea-toggle="'+esc(ideaKey(x))+'">'+(ideaSelected(x)?'✓ Sparat på min idétavla':'＋ Spara fynd på idétavlan')+'</button>';}
function ideaPreviewAction(x){return '<button class="action-btn" data-idea-preview="'+esc(ideaKey(x))+'">✦ Förhandsvisa modul</button>';}
function ideaForKey(key){return (window.NEXUS_IDEAS||[]).find(function(x){return ideaKey(x)===key;});}
function ideaKind(x){var t=(x.title+' '+x.text).toLowerCase();if(/affisch|poster|film|serie|säsong|avsnitt|watchlist|media|omslag/.test(t))return 'media';if(/läs|reader|kapitel|berättelse|typografi|bok|fokusläge|läsning|innehållsförteckning/.test(t))return 'reader';if(/navigation|navigering|meny|drawer|genväg|snabbval|bottom.nav|tabbar|breadcrumb|brödsmul/.test(t))return 'navigation';if(/filter|sortering|sortera|tagg|kategori/.test(t))return 'filter';if(/sök|search|kommandopalett|command.palette/.test(t))return 'search';if(/kunskap|graf|relation|backlink|källa|provenance|länkad data/.test(t))return 'knowledge';if(/statistik|räknare|antal|badge|status|progress|framsteg/.test(t))return 'status';if(/fil|arkiv|dokument|pdf|mapp|upload|uppladd/.test(t))return 'archive';if(/fäll|accordion|expand|collapse|dragspel|visa mer/.test(t))return 'collapse';if(/skeleton|laddning|loading|platshållare/.test(t))return 'loading';if(/tomt läge|empty state|tomt tillstånd|inga resultat|inget innehåll/.test(t))return 'empty';if(/aktivitet|historik|senast uppdaterad|recent|tidslinje/.test(t))return 'activity';if(/accessib|tillgäng|wcag|tryckyta|touch.target|skärmläs|focus.ring|fokusram/.test(t))return 'accessibility';if(/optimist|sparbekräft|återkoppling|toast|bekräftelse|feedback/.test(t))return 'feedback';if(/färg|kontrast|accent|yta|surface|radius|spacing|marginal|reduced motion|skugga|typograf|kanter|border|radie/.test(t))return 'visual';return 'action';}
function ideaSummary(x){var raw=String(x.text||'');var m=raw.match(/Nexus:\s*([\s\S]*?)(?:\n[A-ZÅÄÖ][^:\n]{2,50}:\s|\n---|$)/);var v=(m&&m[1]?m[1]:raw).replace(/[#*_\`]/g,'').replace(/\s+/g,' ').trim();return esc(v.slice(0,220)+(v.length>220?'…':''));}
function ideaTarget(x){var k=ideaKind(x);return k==='reader'?'stories':k==='knowledge'?'knowledge':k==='archive'?'files':k==='navigation'?'home':'films';}
function ideaFallbackMarkup(x){var kind=ideaKind(x),id=esc(x.id),model=esc(x.model),title=esc(x.title),summary=ideaSummary(x),body='';if(kind==='media'){var m=N.data.media[0];body='<button class="ai-module-media" data-open-media="'+m.id+'"><span style="background:'+m.poster+'">'+m.glyph+'</span><b>'+esc(m.title)+'</b><small>'+m.year+' · '+m.type+' · DEMO</small></button>';}else if(kind==='reader'){var s=N.data.stories[0];body='<button class="ai-module-row" data-open-story="'+s.id+'"><span>◈</span><b>'+esc(s.title)+'</b><small>Öppna läsaren →</small></button>';}else if(kind==='navigation'){body='<div class="ai-module-links">'+N.views.slice(0,5).map(function(v){return '<button data-go="'+v.id+'">'+v.icon+' '+esc(v.name)+'</button>';}).join('')+'</div>';}else if(kind==='filter'){body='<div class="ai-module-links">'+['Alla','Film','Serie','Sett','Inte sett'].map(function(v){return '<button data-action="idea-filter:'+v+'">'+v+'</button>';}).join('')+'</div>';}else if(kind==='search'){body='<button class="action-btn" data-action="search">⌕ Öppna global sökning</button>';}else if(kind==='knowledge'){body='<div class="ai-module-links">'+N.data.nodes.slice(0,3).map(function(n){return '<button data-node="'+attr(n.id)+'">◇ '+esc(n.id)+'</button>';}).join('')+'</div>';}else if(kind==='status'){body='<div class="ai-module-states"><span>● Lokal prototyp</span><span>'+N.data.media.length+' filmtitlar i demodata</span><span>Molnsynk: ej ansluten</span></div>';}else if(kind==='archive'){var f=N.data.files[0];body='<button class="ai-module-row" data-file="0"><span>'+f.icon+'</span><b>'+esc(f.name)+'</b><small>'+esc(f.type)+' · öppna →</small></button>';}else if(kind==='loading'){body='<div class="ai-skeleton"><i></i><i></i><i></i></div><small>Platshållare med samma form som innehållet</small>';}else if(kind==='empty'){body='<div class="ai-empty"><b>Inget innehåll ännu</b><p>'+summary+'</p><button class="action-btn" data-go="'+ideaTarget(x)+'">Utforska innehåll →</button></div>';}else if(kind==='activity'){body='<div class="ai-module-states"><span>Senast öppnat · '+esc(N.data.media[0].title)+'</span><span>Fortsätt läsa · '+esc(N.data.stories[0].title)+'</span><button class="action-btn" data-go="activity">Visa aktivitet →</button></div>';}else if(kind==='accessibility'){body='<div class="ai-module-links"><button data-action="font-minus">A−</button><button data-action="font-plus">A+</button><button data-action="focus">Växla fokusläge</button></div><small>Textstorlek och fokusläge ändras i prototypen</small>';}else if(kind==='feedback'){body='<button class="action-btn" data-action="idea-save-demo">Spara modulval</button><small>Visar återkoppling efter åtgärden</small>';}else if(kind==='collapse'){body='<details class="ai-module-details"><summary>Visa modulens innehåll</summary><p>'+summary+'</p></details>';}else if(kind==='visual'){body='<div class="ai-module-swatches"><i></i><i></i><i></i></div><button class="action-btn" data-action="builder">Jämför i komponentbyggaren</button>';}else{body='<p>'+summary+'</p><button class="action-btn" data-go="'+ideaTarget(x)+'">Prova i '+(ideaTarget(x)==='films'?'biblioteket':ideaTarget(x)==='stories'?'läsaren':ideaTarget(x)==='files'?'arkivet':ideaTarget(x)==='knowledge'?'kunskapsbanken':'prototypen')+' →</button>';}return '<article class="ai-module ai-module-'+kind+'"><div class="ai-module-head"><span>KONCEPT · '+model+' · '+id+'</span><strong>'+title+'</strong></div>'+body+'<small class="notice">Generell konceptförhandsvisning · ingen fyndspecifik interaktion</small></article>';}
function ideaModuleMarkup(x){var key=ideaKey(x),def=(window.NEXUS_IDEA_MODULES||{})[key];if(def&&typeof def.render==='function'){var body='';try{body=def.render(x,{esc:esc,attr:attr,data:N.data,views:N.views,button:button});}catch(err){body='<p class="notice">Modulen kunde inte renderas: '+esc(err.message||err)+'</p>';}return '<article class="ai-module ai-module-prototype"><div class="ai-module-head"><span>PROTOTYP · '+esc(x.model)+' · '+esc(x.id)+'</span><strong>'+esc(x.title)+'</strong></div>'+body+'</article>';}return ideaFallbackMarkup(x);}

function aiModulePanel(){var x=ideaForKey(runtime.selectedIdeaKey);if(!x)return sheetHead('Modulen kunde inte hittas','Uppdatera idéarkivet och försök igen.');var registered=!!(window.NEXUS_IDEA_MODULES||{})[ideaKey(x)];return sheetHead(x.title,x.model+' · '+x.id+' · '+(registered?'fyndbaserad prototyp':'generell konceptförhandsvisning'))+ideaModuleMarkup(x)+'<div class="control-row" style="margin-top:14px">'+ideaAction(x)+button('Stäng','close')+'</div><p class="notice">Modulen använder prototypens demodata. Den enskilda idén sparas med modell och fynd-ID i din design.</p>';}
function builtAIModules(){var all=(window.NEXUS_IDEAS||[]).filter(function(x){return ideaSelected(x);});if(!all.length)return '';var shown=all.slice(0,runtime.aiModuleLimit);return section('Dina AI-moduler · '+all.length,'<div class="ai-module-list">'+shown.map(ideaModuleMarkup).join('')+'</div>'+(shown.length<all.length?'<button class="action-btn" data-action="more-ai-modules">Visa fler ('+(all.length-shown.length)+' kvar)</button>':''));}
function ideaBoard(){var ideas=window.NEXUS_IDEAS||[],selected=ideas.filter(function(x){return ideaSelected(x);});return '<div class="callout idea-board" style="margin-bottom:18px"><div class="eyebrow">MIN DESIGN · RESEARCHKOPPLING</div><h2>Valda AI-idéer ('+selected.length+')</h2><p>Här kombinerar du valda förslag från alla åtta modeller. Förslagen är designkrav att utveckla vidare, inte automatiskt färdigbyggda komponenter.</p><div class="control-row">'+button('✦ Komponentverkstad','builder')+button('↓ Exportera min design','export')+'</div>'+(selected.length?'<div class="research-grid">'+selected.slice(0,80).map(function(x){return '<article class="research-item"><span class="research-id">'+esc(x.model)+' · '+esc(x.id)+'</span><h3>'+esc(x.title)+'</h3>'+ideaModuleMarkup(x)+ideaPreviewAction(x)+ideaAction(x)+'</article>';}).join('')+'</div>':'<p class="notice">Välj idéer i arkivet nedan för att lägga till dem i ditt bygge.</p>')+(selected.length>80?'<p>Visar 80 av '+selected.length+' valda idéer.</p>':'')+'</div>';}
function matchingIdeas(){var list=window.NEXUS_IDEAS||[];var q=runtime.researchQuery.trim().toLocaleLowerCase();return list.filter(function(x){return runtime.researchModel==='Alla'||x.model===runtime.researchModel;}).filter(function(x){return !q||(x.title+' '+x.model+' '+x.id+' '+x.text).toLocaleLowerCase().includes(q);});}
function renderResearchResults(){var list=matchingIdeas(),target=byId('researchResults');if(!target)return;target.innerHTML='<div class="eyebrow">'+list.length+' fynd matchar · '+state.ideaBoard.length+' valda för ditt bygge</div><div class="research-grid" style="margin-top:12px">'+list.slice(0,runtime.researchLimit).map(function(x){return '<article class="research-item"><span class="research-id">'+esc(x.model)+' / '+esc(x.id)+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.text)+'</p>'+ideaPreviewAction(x)+ideaAction(x)+'</article>';}).join('')+'</div>'+(list.length>runtime.researchLimit?'<button class="action-btn" data-action="more-ideas" style="margin-top:14px">Visa fler ('+(list.length-runtime.researchLimit)+' kvar) ↓</button>':'');}
function research(){var total=(window.NEXUS_IDEAS||[]).length;return subhead('AI-idéarkiv','Alla '+total+' fynd kan väljas och granskas. Prototyper markeras separat från generella konceptförhandsvisningar. Varje fynd behåller modell och ID.')+'<div class="stats"><div class="card stat"><small>Individuella fynd</small><strong>'+total+'</strong><small>KÄLLTEXT</small></div><div class="card stat"><small>AI-modeller</small><strong>8</strong><small>RAPPORTER</small></div><div class="card stat"><small>Byggbara varianter</small><strong>'+nVariants+'</strong><small>I STUDIO</small></div></div><div class="research-controls"><input type="search" id="researchSearch" class="studio-search" style="flex:1;min-width:200px" placeholder="Sök bland alla fynd…" value="'+attr(runtime.researchQuery)+'"><select id="researchModel" aria-label="Filtrera modell"><option>Alla</option>'+['Copilot','DeepSeek','Grok','Kimi','Meta AI','Vibe','Perplexity','Gemini Argon'].map(function(m){return '<option '+(runtime.researchModel===m?'selected':'')+'>'+m+'</option>';}).join('')+'</select></div><p class="notice">Katalogen innehåller överlapp, motsägelser och experimentella idéer. Ingen avduplicering eller faktaverifiering av rapporternas externa påståenden har gjorts.</p><div id="researchResults"></div>';}
function content(){switch(state.view){case 'films':return films();case 'stories':return stories();case 'reader':return reader();case 'knowledge':return knowledge();case 'files':return files();case 'inbox':return inbox();case 'plugins':return plugins();case 'activity':return activity();case 'settings':return settings();case 'research':return research();default:return home();}}
function builder(){var groups=[...new Set(N.families.map(function(f){return f.group;}))];return sheetHead('Bygg din Nexus Hub','Välj valfri byggdel. Ändringarna syns direkt över hela prototypen.')+'<div class="control-row" style="margin-bottom:16px">'+N.themes.map(function(t){return '<button class="seg '+(state.theme===t.id?'active':'')+'" data-theme="'+t.id+'">'+esc(t.name.split(' · ')[0])+'</button>';}).join('')+'</div><input id="builderSearch" class="studio-search" placeholder="Sök komponenter och varianter…" value="'+attr(runtime.builderFilter)+'"><div class="builder-grid" id="builderResults" style="margin-top:14px">'+builderItems()+'</div><div class="callout" style="margin-top:18px"><div class="eyebrow">HANTERA DIN DESIGN</div><p>Du kan spara konfigurationen som JSON, visa etiketter för skärmbilder och återställa till standardvalen.</p><div class="control-row">'+button('↕ Flytta/dölj moduler','layout')+button('▤ Etiketter','labels')+button('↓ Exportera','export')+button('↑ Importera','import')+'</div></div>';}
function builderItems(){var q=runtime.builderFilter.toLowerCase().trim(),items=N.families.filter(function(f){return !q||(f.name+' '+f.group+' '+f.options.join(' ')).toLowerCase().includes(q);}),groups={};items.forEach(function(f){(groups[f.group]||(groups[f.group]=[])).push(f);});return Object.keys(groups).sort().map(function(g){return '<section class="builder-family-group"><h3>'+esc(g)+'</h3>'+groups[g].map(function(f){return '<button class="builder-item" data-edit-slot="'+attr(f.id)+'"><span class="angle">✦</span><span style="flex:1"><b>'+esc(f.name)+'</b><small>'+esc(chosen(f.id))+'</small></span><span class="num">'+f.options.length+' val</span><span class="angle">›</span></button>';}).join('')+'</section>';}).join('')||'<p class="nothing">Inga komponenter matchar sökningen.</p>';}
function sheetHead(title,desc){return '<div class="sheet-head"><div><div class="eyebrow">NEXUS DESIGN STUDIO</div><h2>'+esc(title)+'</h2><p>'+esc(desc)+'</p></div><button class="sheet-exit" data-action="close" aria-label="Stäng">✕</button></div>';}
function choosePanel(id){var f=family(id);if(!f)return '';return sheetHead(f.name,'Välj en variant. Din design ändras direkt och sparas lokalt.')+'<div class="option-grid">'+f.options.map(function(o,i){return '<button class="option-card '+(variant(id)===i?'selected':'')+'" data-pick="'+f.id+'" data-value="'+i+'"><span class="option-number">'+esc(f.id.toUpperCase())+'-'+String(i+1).padStart(2,'0')+(variant(id)===i?' · VALD':'')+'</span><span class="preview"><i></i><i></i><i></i></span><strong>'+esc(o)+'</strong><small>'+(variant(id)===i?'Aktiv i din prototyp':'Tryck för att använda den här varianten')+'</small></button>';}).join('')+'</div><p class="notice">Tips: håll inne på ett kort eller använd ✦ Byt för att återvända till alternativen.</p>';}
function layoutPanel(){return sheetHead('Ordna startsidan','Flytta eller dölj modulerna. Dina val sparas direkt.')+'<div class="stack">'+state.order.map(function(id,i){var m=N.data.modules.find(function(x){return x.id===id;});if(!m)return '';var hidden=state.hidden.includes(id);return '<div class="card layout-item" style="display:flex;align-items:center;gap:8px"><span style="font-size:24px;color:var(--accent)">'+m.icon+'</span><div style="flex:1;min-width:0"><strong style="font-size:12px">'+esc(m.name)+'</strong><small style="display:block;color:var(--muted)">'+(hidden?'Dold':'Visas på startsidan')+'</small></div><button class="mini-btn" data-shift="'+id+'" data-direction="-1" aria-label="Flytta upp" '+(i===0?'disabled':'')+'>↑</button><button class="mini-btn" data-shift="'+id+'" data-direction="1" aria-label="Flytta ner" '+(i===state.order.length-1?'disabled':'')+'>↓</button><button class="mini-btn" data-toggle-module="'+id+'">'+(hidden?'Visa':'Dölj')+'</button></div>';}).join('')+'</div><div class="control-row" style="margin-top:17px">'+button('Klar','close','primary')+'</div>';}
function detailPanel(){var m=N.data.media.find(function(x){return x.id===runtime.selectedMedia;});if(!m)return '';return sheetHead(m.title,'Filmdetaljer · demobibliotek')+slot('mediaDetail','<div class="detail-hero" style="background:'+m.poster+'"><h2>'+esc(m.title)+'</h2></div><div class="detail-meta"><span class="chip">'+m.year+'</span><span class="chip">'+m.type+'</span><span class="chip">★ '+m.rating+'</span>'+m.genres.map(function(g){return '<span class="chip">'+esc(g)+'</span>';}).join('')+'</div><p class="notice">'+esc(m.progress)+' · Illustrativ metadata, inga riktiga uppgifter ändras.</p><div class="control-row" style="margin:18px 0">'+button((state.watched[m.id]?'✓ Markerad som sedd':'Markera som sedd'),'watched','primary')+button('Byt detaljlayout','edit-media-detail')+'</div>')+(m.type==='Serie'?slot('season','<h3>Säsonger</h3><div class="simple-list">'+[1,2,3].map(function(s){return '<button class="builder-item" data-action="season-demo"><strong>Säsong '+s+'</strong><span class="num">Visa avsnitt ›</span></button>';}).join('')+'</div>'):'');}
function nodePanel(){return sheetHead(runtime.selectedNode||'Relation','Kunskapsobjekt · exempeldata')+'<div class="callout"><div class="eyebrow">FORSKNINGSOBJEKT</div><h3>'+esc(runtime.selectedNode)+'</h3><p>Den här noden är kopplad till Djatlovpasset. Välj en annan nod i grafen eller byt grafvariant med ett långt tryck.</p>'+button('Läs dossier →','open-dossier','primary')+'</div>';}
function filePanel(){var f=N.data.files[runtime.selectedFile];if(!f)return '';return sheetHead(f.name,'Dokumentinformation · exempel')+'<div class="callout"><p>Format: '+esc(f.type)+'<br>Storlek: '+esc(f.size)+'<br>Status: Demoobjekt<br>Källa: Designlaboratoriet</p>'+button('Byt dokumentkort','edit-filecard')+'</div>';}
function menuPanel(){return sheetHead('Alla vyer','Öppna valfri del av den kompletta demonstrationens navigering.')+'<div class="builder-grid">'+N.views.map(function(v){return '<button class="builder-item" data-go="'+v.id+'"><span class="angle">'+v.icon+'</span><b style="flex:1">'+esc(v.name)+'</b>›</button>';}).join('')+'</div>';}
function searchPanel(){var commands=variant('ux006')>0;return sheetHead(commands?'Kommandopalett':'Sök i Nexus Hub',commands?(variant('ux006')>1?'Sök eller kör en genväg · Ctrl/⌘ K öppnar paletten.':'Sök i hela prototypen eller välj en genväg.'):'Demonstration av global sökning över filmer, mysterier, filer och vyer.')+(commands?'<div class="ux-commands"><button data-action="builder">✦ Bygg</button><button data-go="films">Film</button><button data-go="stories">Berättelser</button><button data-go="research">AI-idéer</button></div>':'')+'<input class="studio-search" id="globalSearch" placeholder="'+(commands?'Sök eller skriv ett kommando…':'Skriv en titel eller funktion…')+'"><div id="globalResults" style="margin-top:15px"></div>';}
function searchResults(q){q=(q||'').toLocaleLowerCase();var arr=N.views.map(function(v){return {name:v.name,sub:'Vy',action:'data-go="'+v.id+'"'};}).concat(N.data.media.map(function(m){return {name:m.title,sub:m.type,action:'data-open-media="'+m.id+'"'};}),N.data.stories.map(function(s){return {name:s.title,sub:'Berättelse',action:'data-open-story="'+s.id+'"'};}),N.data.files.map(function(f,i){return {name:f.name,sub:'Arkivfil',action:'data-file="'+i+'"'};}));return '<div class="simple-list">'+arr.filter(function(x){return x.name.toLowerCase().includes(q);}).slice(0,12).map(function(x){return '<button class="builder-item" '+x.action+'><b style="flex:1">'+esc(x.name)+'</b><small>'+esc(x.sub)+'</small>↗</button>';}).join('')+'</div>';}
function quickPanel(){var items=[['films','Öppna Film & serier'],['reader','Öppna läsaren'],['stories','Utforska berättelser'],['knowledge','Kunskapsgraf'],['files','Hitta dokument'],['research','AI-idéarkiv'],['settings','Mina inställningar']];if(variant('ux001'))items.sort(function(a,b){return (a[0]===state.view?-1:0)-(b[0]===state.view?-1:0);});if(variant('ux001')>1){var current=items.filter(function(x){return x[0]===state.view;});var rest=items.filter(function(x){return x[0]!==state.view;});items=current.concat(rest);}return sheetHead('Snabbåtgärder','Genvägar med din aktuella vy överst.')+'<div class="ux-current">Aktuell vy: <b>'+esc((N.views.find(function(v){return v.id===state.view;})||N.views[0]).name)+'</b></div><div class="builder-grid">'+items.map(function(x){return '<button class="builder-item" data-go="'+x[0]+'"><b>'+x[1]+'</b><span class="num">→</span></button>';}).join('')+'</div>';}
function chaptersPanel(){return sheetHead('Kapitel','Välj ett kapitel i demonstrationen.')+['Den sista expeditionen','Spåren på bergssluttningen','Frågor och teorier'].map(function(h,i){return '<button class="builder-item" data-chapter="'+i+'"><span class="num">0'+(i+1)+'</span><b>'+h+'</b>→</button>';}).join('');}
function renderSheet(){if(!runtime.sheet)return '';var inner='';switch(runtime.sheet){case 'builder':inner=builder();break;case 'layout':inner=layoutPanel();break;case 'choose':inner=choosePanel(runtime.slot);break;case 'detail':inner=detailPanel();break;case 'node':inner=nodePanel();break;case 'file':inner=filePanel();break;case 'menu':inner=menuPanel();break;case 'search':inner=searchPanel();break;case 'quick':inner=quickPanel();break;case 'chapters':inner=chaptersPanel();break;case 'ai-module':inner=aiModulePanel();break;default:return '';}return '<div class="overlay '+(runtime.sheet==='search'?'search-wrapper v-'+variant('search'):'')+'" id="overlay" data-overlay="1"><div class="sheet" role="dialog" aria-modal="true"><div class="sheet-handle"></div>'+inner+'</div></div>';}
function render(){document.body.dataset.theme=state.theme;['surface','shape','type','density','motion','ux004','ux005','ux002','ux003','ux009'].forEach(function(k){document.body.dataset[k]=String(variant(k));});document.body.classList.toggle('labels-on',!!state.labels);document.body.classList.toggle('edit-on',!!state.edit);document.body.classList.toggle('focus-mode',!!state.focus);byId('app').innerHTML='<div class="studio-shell">'+sidebar()+'<main class="main">'+topbar()+'<div class="view">'+content()+'</div></main>'+bottomNav()+quickAction()+'</div>'+renderSheet();if(state.view==='research')renderResearchResults();if(runtime.sheet==='search')byId('globalResults').innerHTML=searchResults('');document.title=(N.views.find(function(x){return x.id===state.view;})||N.views[0]).name+' · Nexus Design Studio';}
function openSheet(name){runtime.sheet=name;render();if(name==='search'){var e=byId('globalSearch');if(e)e.focus();}}
function editSlot(id){if(!family(id))return;runtime.slot=id;openSheet('choose');}
function setTheme(id){if(!N.themes.some(function(t){return t.id===id;}))return;state.theme=id;save();render();toast('Designriktning: '+id);}
function exportConfig(){var data={format:'nexus-design-studio',version:1,exportedAt:new Date().toISOString(),theme:state.theme,picks:state.picks,order:state.order,hidden:state.hidden,labels:state.labels,edit:state.edit,fontSize:state.fontSize,ideaBoard:state.ideaBoard,collapsedSections:state.collapsedSections||{}};var blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});var url=URL.createObjectURL(blob);var link=document.createElement('a');link.href=url;link.download='nexus-hub-min-design.json';document.body.appendChild(link);link.click();link.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);toast('Din design är exporterad');}
function importConfig(){var input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=function(){var file=input.files&&input.files[0];if(!file)return;var rd=new FileReader();rd.onload=function(){try{var d=JSON.parse(String(rd.result));if(d.format!=='nexus-design-studio'||d.version!==1||typeof d.picks!=='object'||!d.picks||Array.isArray(d.picks))throw new Error('Fel format');var picks={};N.families.forEach(function(f){var n=Number(d.picks[f.id]);picks[f.id]=Number.isInteger(n)?Math.max(0,Math.min(n,f.options.length-1)):0;});state.picks=picks;state.theme=N.themes.some(function(t){return t.id===d.theme;})?d.theme:DEFAULT.theme;state.order=Array.isArray(d.order)?d.order.filter(function(x){return N.data.modules.some(function(m){return m.id===x;});}):DEFAULT.order.slice();state.hidden=Array.isArray(d.hidden)?d.hidden.filter(function(x){return typeof x==='string';}):[];state.labels=!!d.labels;state.edit=!!d.edit;state.fontSize=Math.max(14,Math.min(27,Number(d.fontSize)||18));state.ideaBoard=Array.isArray(d.ideaBoard)?d.ideaBoard.filter(function(x){return typeof x==='string'&&x.length<150;}):[];state.collapsedSections=d.collapsedSections&&typeof d.collapsedSections==='object'?d.collapsedSections:{};runtime.sheet=null;save();render();toast('Designen importerades');}catch(e){toast('Filen är inte en giltig Nexus Design Studio-export');}};rd.readAsText(file);};input.click();}
function handleAction(name){if(name.indexOf('idea-filter:')===0){runtime.filmFilter=name.slice(12);setView('films');return;}if(name==='idea-save-demo'){toast('Modulvalet sparades lokalt');return;}if(name==='back-to-top'){window.scrollTo({top:0,behavior:'smooth'});return;}switch(name){
case 'menu':openSheet('menu');break;case 'layout':openSheet('layout');break;case 'search':openSheet('search');break;case 'builder':openSheet('builder');break;case 'quick':openSheet('quick');break;
case 'labels':state.labels=!state.labels;save();render();break;case 'edit':state.edit=!state.edit;save();render();break;case 'close':runtime.sheet=null;render();break;
case 'export':exportConfig();break;case 'import':importConfig();break;
case 'reset':if(confirm('Återställa alla lokala designval?')){state=JSON.parse(JSON.stringify(DEFAULT));runtime.sheet=null;save();render();}break;
case 'font-plus':state.fontSize=Math.min(27,state.fontSize+2);save();render();break;case 'font-minus':state.fontSize=Math.max(14,state.fontSize-2);save();render();break;
case 'footnote':runtime.readerFoot=!runtime.readerFoot;render();break;case 'focus':state.focus=!state.focus;save();render();break;
case 'chapters':openSheet('chapters');break;case 'chapter-next':runtime.chapter=(runtime.chapter+1)%3;render();break;case 'chapter-prev':runtime.chapter=(runtime.chapter+2)%3;render();break;
case 'watched':state.watched[runtime.selectedMedia]=!state.watched[runtime.selectedMedia];save();render();break;
case 'season-demo':toast('Avsnittslista · demonstration');break;
case 'edit-media-detail':editSlot('mediaDetail');break;case 'edit-filecard':editSlot('fileCard');break;case 'open-dossier':state.selectedStory='dyatlov';setView('reader');break;
case 'more-ideas':runtime.researchLimit+=25;renderResearchResults();break;case 'more-ai-modules':runtime.aiModuleLimit+=12;render();break;case 'ux-random':if(variant('ux008')>1&&Math.random()<0.5){var media=N.data.media[Math.floor(Math.random()*N.data.media.length)];runtime.selectedMedia=media.id;openSheet('detail');}else{var story=N.data.stories[Math.floor(Math.random()*N.data.stories.length)];state.selectedStory=story.id;runtime.chapter=0;setView('reader');}break;}}
document.addEventListener('click',function(e){
if(e.target.matches('#overlay')){runtime.sheet=null;render();return;}
var t=e.target.closest('[data-action],[data-go],[data-edit-slot],[data-pick],[data-theme],[data-filter],[data-open-media],[data-open-story],[data-node],[data-file],[data-plugin],[data-inbox],[data-chapter],[data-shift],[data-toggle-module],[data-toggle-section],[data-idea-toggle],[data-idea-preview]');
if(!t)return;
if(runtime.suppressClick&&Date.now()<runtime.suppressClick){e.preventDefault();return;}
if(t.hasAttribute('data-idea-preview')){runtime.selectedIdeaKey=t.getAttribute('data-idea-preview');openSheet('ai-module');return;}
if(t.hasAttribute('data-idea-toggle')){var key=t.getAttribute('data-idea-toggle'),ix=state.ideaBoard.indexOf(key);if(ix<0)state.ideaBoard.push(key);else state.ideaBoard.splice(ix,1);save();render();toast(ix<0?'AI-idén tillagd i ditt bygge':'AI-idén borttagen');return;}
if(t.hasAttribute('data-shift')){var id=t.getAttribute('data-shift'),delta=Number(t.getAttribute('data-direction')),i=state.order.indexOf(id),j=i+delta;if(i>=0&&j>=0&&j<state.order.length){state.order.splice(i,1);state.order.splice(j,0,id);save();render();}return;}
if(t.hasAttribute('data-toggle-module')){var id=t.getAttribute('data-toggle-module'),idx=state.hidden.indexOf(id);if(idx<0)state.hidden.push(id);else state.hidden.splice(idx,1);save();render();return;}
if(t.hasAttribute('data-toggle-section')){var sid=t.getAttribute('data-toggle-section');state.collapsedSections=state.collapsedSections||{};state.collapsedSections[sid]=!state.collapsedSections[sid];save();render();return;}
if(t.hasAttribute('data-action')){handleAction(t.getAttribute('data-action'));return;}
if(t.hasAttribute('data-go')){setView(t.getAttribute('data-go'));return;}
if(t.hasAttribute('data-edit-slot')){editSlot(t.getAttribute('data-edit-slot'));return;}
if(t.hasAttribute('data-pick')){var id=t.getAttribute('data-pick'),v=Number(t.getAttribute('data-value'));runtime.sheet=null;changePick(id,v);return;}
if(t.hasAttribute('data-theme')){setTheme(t.getAttribute('data-theme'));return;}
if(t.hasAttribute('data-filter')){runtime.filmFilter=t.getAttribute('data-filter');render();return;}
if(t.hasAttribute('data-open-media')){runtime.selectedMedia=t.getAttribute('data-open-media');openSheet('detail');return;}
if(t.hasAttribute('data-open-story')){state.selectedStory=t.getAttribute('data-open-story');runtime.chapter=0;setView('reader');return;}
if(t.hasAttribute('data-node')){runtime.selectedNode=t.getAttribute('data-node');openSheet('node');return;}
if(t.hasAttribute('data-file')){runtime.selectedFile=Number(t.getAttribute('data-file'));openSheet('file');return;}
if(t.hasAttribute('data-plugin')){var p=t.getAttribute('data-plugin');state.plugins[p]=state.plugins[p]===false;save();render();return;}
if(t.hasAttribute('data-inbox')){var n=t.getAttribute('data-inbox');state.inboxRead[n]=!state.inboxRead[n];save();render();return;}
if(t.hasAttribute('data-chapter')){runtime.chapter=Number(t.getAttribute('data-chapter'));runtime.sheet=null;render();return;}
});
document.addEventListener('input',function(e){if(e.target.id==='researchSearch'){runtime.researchQuery=e.target.value;runtime.researchLimit=25;renderResearchResults();}else if(e.target.id==='builderSearch'){runtime.builderFilter=e.target.value;var el=byId('builderResults');if(el)el.innerHTML=builderItems();}else if(e.target.id==='globalSearch'){var el=byId('globalResults');if(el)el.innerHTML=searchResults(e.target.value);}else if(e.target.id==='mediaSearch'){runtime.mediaSearch=e.target.value;var f=filteredMedia();var s=document.querySelector('[data-family=mediaLayout] .poster-grid');if(s)s.innerHTML=f.map(postercard).join('');}});
document.addEventListener('change',function(e){if(e.target.id==='researchModel'){runtime.researchModel=e.target.value;runtime.researchLimit=25;renderResearchResults();}});
var pressTimer=null,pressStart=null;function stopPress(){if(pressTimer){clearTimeout(pressTimer);pressTimer=null;}pressStart=null;}
document.addEventListener('pointerdown',function(e){if(e.button!==0&&e.pointerType==='mouse')return;if(e.target.closest('input,textarea,select,.overlay'))return;var target=e.target.closest('[data-slot]');if(!target)return;pressStart={x:e.clientX,y:e.clientY,id:target.getAttribute('data-slot')};pressTimer=setTimeout(function(){if(!pressStart)return;runtime.suppressClick=Date.now()+700;var id=pressStart.id;stopPress();if(navigator.vibrate)navigator.vibrate(20);editSlot(id);},550);},{passive:true});
document.addEventListener('pointermove',function(e){if(pressStart&&Math.hypot(e.clientX-pressStart.x,e.clientY-pressStart.y)>12)stopPress();},{passive:true});
['pointerup','pointercancel','scroll'].forEach(function(k){document.addEventListener(k,stopPress,{passive:true,capture:k==='scroll'});});
document.addEventListener('contextmenu',function(e){var target=e.target.closest('[data-slot]');if(target&&!e.target.closest('input,textarea,select')){e.preventDefault();editSlot(target.getAttribute('data-slot'));}});
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&runtime.sheet){runtime.sheet=null;render();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSheet('search');}});
render();

})();